import{_ as e,o as l,c as s,a0 as a}from"./chunks/framework.DQOulFGV.js";const x=JSON.parse('{"title":"PostgreSQL vs MySQL 全面对比","description":"","frontmatter":{"doc_id":"pg-PG与MySQL对比","title":"PostgreSQL vs MySQL 全面对比"},"headers":[],"relativePath":"postgresql/01-PG与MySQL对比.md","filePath":"postgresql/01-PG与MySQL对比.md"}'),d={name:"postgresql/01-PG与MySQL对比.md"};function r(n,t,g,o,i,y){return l(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="postgresql-vs-mysql-全面对比" tabindex="-1">PostgreSQL vs MySQL 全面对比 <a class="header-anchor" href="#postgresql-vs-mysql-全面对比" aria-label="Permalink to &quot;PostgreSQL vs MySQL 全面对比&quot;">​</a></h1><blockquote><p><strong>核心问题</strong>：什么时候选 PostgreSQL？什么时候选 MySQL？两者核心差异是什么？</p></blockquote><hr><h2 id="它解决了什么问题" tabindex="-1">它解决了什么问题？ <a class="header-anchor" href="#它解决了什么问题" aria-label="Permalink to &quot;它解决了什么问题？&quot;">​</a></h2><p>MySQL 在某些场景下力不从心，PostgreSQL 针对这些场景做了专项优化：</p><table tabindex="0"><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">MySQL 的问题</th><th style="text-align:left;">PostgreSQL 的解决方案</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>JSON 数据存储与查询</strong></td><td style="text-align:left;">JSON 支持较弱，无法高效索引 JSON 字段</td><td style="text-align:left;">原生 JSONB（二进制存储，可建 GIN 索引）</td></tr><tr><td style="text-align:left;"><strong>复杂分析查询</strong></td><td style="text-align:left;">窗口函数、CTE 递归查询支持不完整（8.0 前）</td><td style="text-align:left;">完整支持 ROW_NUMBER/RANK/LAG 等窗口函数</td></tr><tr><td style="text-align:left;"><strong>地理信息处理</strong></td><td style="text-align:left;">无专用 GIS 索引</td><td style="text-align:left;">GiST 索引 + PostGIS 扩展</td></tr><tr><td style="text-align:left;"><strong>严格的 SQL 标准</strong></td><td style="text-align:left;">GROUP BY 等场景较宽松</td><td style="text-align:left;">严格遵循 SQL 标准</td></tr></tbody></table><hr><h2 id="生活类比-专业厨师-vs-家常厨师" tabindex="-1">生活类比：专业厨师 vs 家常厨师 <a class="header-anchor" href="#生活类比-专业厨师-vs-家常厨师" aria-label="Permalink to &quot;生活类比：专业厨师 vs 家常厨师&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">对比</th><th style="text-align:left;">MySQL</th><th style="text-align:left;">PostgreSQL</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>定位</strong></td><td style="text-align:left;">家常厨师：简单快手，适合日常</td><td style="text-align:left;">专业厨师：功能全面，适合复杂菜肴</td></tr><tr><td style="text-align:left;"><strong>优势</strong></td><td style="text-align:left;">简单 CRUD 性能好，生态成熟</td><td style="text-align:left;">复杂查询、JSON、GIS 场景更强</td></tr><tr><td style="text-align:left;"><strong>劣势</strong></td><td style="text-align:left;">高级特性支持有限</td><td style="text-align:left;">运维复杂，国内生态相对较少</td></tr></tbody></table><hr><h2 id="核心差异对比表" tabindex="-1">核心差异对比表 <a class="header-anchor" href="#核心差异对比表" aria-label="Permalink to &quot;核心差异对比表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">PostgreSQL</th><th style="text-align:left;">MySQL</th><th style="text-align:left;">选择依据</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>JSON 支持</strong></td><td style="text-align:left;">原生 JSONB（二进制存储，可索引）</td><td style="text-align:left;">JSON 类型支持较弱，索引能力有限</td><td style="text-align:left;">需要存储和查询 JSON 选 PG</td></tr><tr><td style="text-align:left;"><strong>索引类型</strong></td><td style="text-align:left;">B-tree / Hash / GIN / GiST / BRIN</td><td style="text-align:left;">主要是 B-tree，全文索引有限</td><td style="text-align:left;">需要全文检索/GIS 选 PG</td></tr><tr><td style="text-align:left;"><strong>窗口函数</strong></td><td style="text-align:left;">完整支持（ROW_NUMBER/RANK/LAG 等）</td><td style="text-align:left;">MySQL 8.0+ 才支持，早期版本不支持</td><td style="text-align:left;">需要复杂分析查询选 PG</td></tr><tr><td style="text-align:left;"><strong>事务隔离</strong></td><td style="text-align:left;">支持真正的 Serializable（SSI）</td><td style="text-align:left;">Serializable 通过锁实现，性能差</td><td style="text-align:left;">需要严格串行化选 PG</td></tr><tr><td style="text-align:left;"><strong>MVCC 实现</strong></td><td style="text-align:left;">多版本行存储（堆表中保留旧版本）</td><td style="text-align:left;">Undo Log 回滚段（独立存储）</td><td style="text-align:left;">PG 需要 VACUUM，MySQL 自动回收</td></tr><tr><td style="text-align:left;"><strong>表继承</strong></td><td style="text-align:left;">支持（面向对象特性）</td><td style="text-align:left;">不支持</td><td style="text-align:left;">分区表场景</td></tr><tr><td style="text-align:left;"><strong>SQL 标准</strong></td><td style="text-align:left;">严格遵循 SQL 标准</td><td style="text-align:left;">部分宽松（如 GROUP BY 不严格）</td><td style="text-align:left;">需要严格 SQL 标准选 PG</td></tr><tr><td style="text-align:left;"><strong>国内生态</strong></td><td style="text-align:left;">相对较少，但增长迅速</td><td style="text-align:left;">成熟，文档/工具丰富</td><td style="text-align:left;">团队熟悉度和生态支持</td></tr><tr><td style="text-align:left;"><strong>适用场景</strong></td><td style="text-align:left;">复杂查询、JSON、GIS、分析型</td><td style="text-align:left;">高并发读写、互联网业务</td><td style="text-align:left;">根据业务特点选择</td></tr></tbody></table><hr><h2 id="选型决策" tabindex="-1">选型决策 <a class="header-anchor" href="#选型决策" aria-label="Permalink to &quot;选型决策&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">选 PostgreSQL</th><th style="text-align:left;">选 MySQL</th></tr></thead><tbody><tr><td style="text-align:left;">需要存储和查询 JSON/JSONB 数据</td><td style="text-align:left;">高并发简单读写（如电商商品列表）</td></tr><tr><td style="text-align:left;">需要复杂分析查询（窗口函数、CTE）</td><td style="text-align:left;">团队对 MySQL 更熟悉，生态更成熟</td></tr><tr><td style="text-align:left;">地理信息系统（配合 PostGIS）</td><td style="text-align:left;">需要简单快速部署</td></tr><tr><td style="text-align:left;">需要严格的 SQL 标准</td><td style="text-align:left;">国内云厂商支持更完善</td></tr></tbody></table><blockquote><p><strong>选型建议</strong>：需要复杂查询、JSON 存储、地理信息、严格事务 → 选 PG；需要极致读写性能、成熟生态、简单部署 → 选 MySQL。</p></blockquote><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：PostgreSQL 和 MySQL 最核心的区别是什么？</strong></p><blockquote><p>三个核心差异：① <strong>功能丰富度</strong>：PG 支持原生 JSONB（可索引）、完整窗口函数、GIN/GiST 等多种索引类型；② <strong>MVCC 实现</strong>：PG 将旧版本行存储在堆表中，需要 VACUUM 清理；MySQL 使用 Undo Log，事务提交后自动回收，无表膨胀问题；③ <strong>SQL 标准</strong>：PG 更严格，MySQL 在 GROUP BY 等场景下较宽松。</p></blockquote><p><strong>Q：什么时候选 PostgreSQL，什么时候选 MySQL？</strong></p><blockquote><p>需要 JSON 存储查询、复杂分析（窗口函数/CTE）、地理信息（PostGIS）、严格 SQL 标准 → 选 PG；高并发简单读写、团队熟悉 MySQL、需要成熟生态 → 选 MySQL。</p></blockquote>',22)])])}const S=e(d,[["render",r]]);export{x as __pageData,S as default};
